using System;using System.IO;using System.Linq;using System.Collections;using UnityEditor;using UnityEngine;using JarVis.Warehouse.UI;using Cdm.Figma.UI;
namespace ProjectBootstrap {
 [InitializeOnLoad] public static class ScannerSweepReview {
 static double next;static ScannerSweepReview(){EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1;if(!File.Exists("Library/JarVisReviewSweep.request")||EditorApplication.isCompiling)return;if(EditorApplication.isPlaying){File.Delete("Library/JarVisReviewSweep.request");new GameObject("Sweep bounds review").AddComponent<SweepBoundsRunner>();}};}
 }
 public sealed class SweepBoundsRunner:MonoBehaviour {
 IEnumerator Start(){var nav=FindAnyObjectByType<ImportedFigmaNavigation>();var previous=nav.CurrentScreen;var root=nav.screens.First(s=>s.id=="5:331").root;var scanner=root.GetComponent<ImportedCameraScanner>();bool enabled=scanner.enabled;scanner.enabled=false;nav.Show("5:331",false);yield return null;yield return null;var frame=root.GetComponentsInChildren<FigmaNode>(true).First(n=>n.nodeName=="scan-target-frame").rectTransform;var line=(RectTransform)frame.Find("Red scanning sweep");var corners=new Vector3[4];bool inside=true;float min=float.MaxValue,max=float.MinValue;float end=Time.unscaledTime+2.1f;while(Time.unscaledTime<end){line.GetWorldCorners(corners);foreach(var corner in corners){var point=frame.InverseTransformPoint(corner);if(!frame.rect.Contains(new Vector2(point.x,point.y)))inside=false;}min=Mathf.Min(min,line.anchoredPosition.y);max=Mathf.Max(max,line.anchoredPosition.y);yield return null;}ComposerLocalizationRunner.Capture(nav,"QR-Sweep-Inside-Frame.png");File.WriteAllText("Logs/ComposerLocalizationReview/ScannerSweep.txt",(inside&&max-min>20?"PASS":"FAIL")+" "+DateTime.UtcNow.ToString("O")+"\nRed sweep corners remain inside scan-target-frame; vertical travel="+(max-min).ToString("F1")+". Camera disabled during UI check.");nav.Show(previous,false);scanner.enabled=enabled;Destroy(gameObject);}
 }
}
